// TypeScript: function add(a: number, b: number): number
// In JS we enforce it at runtime instead.
function add(a, b) {
  if (typeof a !== "number" || typeof b !== "number") {
    throw new TypeError("add expects numbers");
  }
  return a + b;
}
console.log(add(2, 3));

