// TypeScript: function first(strings: string[]): string
function first(arr) {
  if (!Array.isArray(arr) || typeof arr[0] !== "string") {
    throw new TypeError("expected an array of strings");
  }
  return arr[0];
}
console.log(first(["a", "b"]));

