// TypeScript narrows with typeof — do the same in JS.
function describe(x) {
  if (typeof x === "number") return "number:" + x;
  if (typeof x === "string") return "string:" + x;
  return "unknown";
}
console.log(describe(5) + "," + describe("hi") + "," + describe(null));

